from pathlib import Path
import csv,json,base64,html,zipfile,io
ROOT=Path(__file__).resolve().parents[1]
PARTS=json.loads((ROOT/'docs/parts.json').read_text())

def dl(path,label=None):
    p=ROOT/path
    if not p.exists():raise FileNotFoundError(p)
    mime='application/octet-stream'
    return '<a download="'+html.escape(p.name)+'" href="data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode()+'">'+html.escape(label or p.name)+'</a>'

def link(url,label):return '<a href="'+html.escape(url)+'" target="_blank" rel="noopener">'+label+' ↗</a>'
rows=''
materials={'01_case':'Clear / natural PETG','02_switch_plate':'White or clear PETG','03_round_foot':'White or gray PETG','04_joystick_cradle':'Black PETG','05_touch_cap':'Black PETG','06_encoder_knob':'White PETG','07_led_baffle':'Black PETG','08_keycap_1u':'6 clear + 5 white PETG','09_keycap_2u_dual_stem':'White PETG','10_switch_fit_coupon':'Same as plate','11_stem_insert_coupon':'Same as cap / case'}
for name,p in PARTS.items():
    rows+=f'<tr><td><strong>{html.escape(name.replace("_"," "))}</strong><small>{html.escape(p["notes"])}</small></td><td>{p["qty"]}</td><td>{materials[name]}</td><td>{dl("stl/"+name+".stl","STL")} · {dl("step/"+name+".step","STEP")}</td></tr>'
bom=''
for r in csv.DictReader((ROOT/'docs/bom.csv').open()):
    bom+=f'<tr data-route="{r["route"]}"><td><input type="checkbox" aria-label="Bought {html.escape(r["item"])}"></td><td><strong>{link(r["url"],html.escape(r["item"]))}</strong><small>{html.escape(r["notes"])}</small></td><td>{r["quantity_to_buy"]}<small>Use: {r["quantity_used"]}</small></td><td>{r["estimated_USD"]}</td><td><span class="tag">{r["route"]}</span></td></tr>'
# Embedded download makes the HTML usable as a single self-contained file.
packed=io.BytesIO()
with zipfile.ZipFile(packed,'w',zipfile.ZIP_DEFLATED) as z:
    for folder in ['cad','stl','step','firmware','tools','docs','animation']:
        for p in sorted((ROOT/folder).rglob('*')):
            if p.is_file() and '__pycache__' not in p.parts and p.name!='make_guide.py':z.write(p,p.relative_to(ROOT))
    for n in ['README.md','requirements.txt','assembly-animation.html']:z.write(ROOT/n,n)
zip_data=base64.b64encode(packed.getvalue()).decode()
preview=base64.b64encode((ROOT/'docs/cad-preview.png').read_bytes()).decode()
wiring=(ROOT/'docs/wiring.svg').read_text()
